-- Greece milestone translations (ES/DE/FR) — replaces the
-- English-placeholder draft stub generated by new_country_scaffold.py.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-mydata-mandatory', 'es', 'El reporte en tiempo real de myDATA se vuelve obligatorio', 'La plataforma myDATA (My Digital Accounting and Tax Application) de AADE se vuelve obligatoria para todos los contribuyentes griegos, exigiendo la transmisión en tiempo real o casi real de los datos de facturas y contabilidad. Cada transacción recibe una marca de registro única (MARK) y un código QR de AADE — la columna vertebral de reporte sobre la que se construye cada capa posterior de facturación electrónica.', '["Regístrese para el reporte myDATA a través del portal de AADE o una integración certificada de ERP/contabilidad", "Confirme que sus sistemas generan correctamente el MARK y el código QR para cada factura"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-mydata-mandatory', 'de', 'Die Echtzeitmeldung über myDATA wird verpflichtend', 'Die myDATA-Plattform (My Digital Accounting and Tax Application) der AADE wird für alle griechischen Steuerpflichtigen verpflichtend und verlangt die Echtzeit- oder Nahe-Echtzeit-Übermittlung von Rechnungs- und Buchhaltungsdaten. Jede Transaktion erhält eine eindeutige Registrierungsmarke (MARK) und einen QR-Code von der AADE — das Meldungsrückgrat, auf dem jede spätere E-Rechnungsschicht aufbaut.', '["Registrieren Sie sich für die myDATA-Meldung über das AADE-Portal oder eine zertifizierte ERP-/Buchhaltungsintegration", "Bestätigen Sie, dass Ihre Systeme das MARK und den QR-Code für jede Rechnung korrekt erzeugen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-mydata-mandatory', 'fr', 'La déclaration en temps réel via myDATA devient obligatoire', 'La plateforme myDATA (My Digital Accounting and Tax Application) de l''AADE devient obligatoire pour tous les contribuables grecs, exigeant la transmission en temps réel ou quasi réel des données de factures et de comptabilité. Chaque transaction reçoit une marque d''enregistrement unique (MARK) et un code QR de l''AADE — l''épine dorsale de déclaration sur laquelle repose chaque couche ultérieure de facturation électronique.', '["Inscrivez-vous à la déclaration myDATA via le portail de l''AADE ou une intégration ERP/comptable certifiée", "Confirmez que vos systèmes génèrent correctement le MARK et le code QR pour chaque facture"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2g-2025', 'es', 'La facturación electrónica B2G se vuelve totalmente obligatoria', 'Tras un despliegue por fases en las administraciones públicas desde septiembre de 2023, la facturación electrónica B2G se vuelve totalmente obligatoria para todos los contratos públicos que superen los 2.500 €. Los proveedores presentan facturas conformes con EN 16931 (CIUS griego de Peppol) para su validación en myDATA y asignación de MARK, y su posterior transmisión a través de puntos de acceso Peppol acreditados al Centro Nacional de Interoperabilidad (KED).', '["Confirme que su punto de acceso Peppol está acreditado para el CIUS griego", "Compruebe si su contraparte del sector público concreta está dentro del umbral de contrato de 2.500 €"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2g-2025', 'de', 'Die B2G-E-Rechnung wird vollständig verpflichtend', 'Nach einer stufenweisen Einführung in öffentlichen Verwaltungen seit September 2023 wird die B2G-E-Rechnung für alle öffentlichen Aufträge über 2.500 € vollständig verpflichtend. Lieferanten reichen EN-16931-konforme Rechnungen (griechisches Peppol-CIUS) zur Validierung bei myDATA und MARK-Vergabe ein, anschließend erfolgt die Übermittlung über akkreditierte Peppol-Zugangspunkte an das nationale Interoperabilitätszentrum (KED).', '["Bestätigen Sie, dass Ihr Peppol-Zugangspunkt für das griechische CIUS akkreditiert ist", "Prüfen Sie, ob Ihr konkreter öffentlicher Auftraggeber innerhalb der 2.500-€-Auftragsschwelle liegt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2g-2025', 'fr', 'La facturation électronique B2G devient entièrement obligatoire', 'Après un déploiement progressif dans les administrations publiques depuis septembre 2023, la facturation électronique B2G devient entièrement obligatoire pour tous les marchés publics dépassant 2 500 €. Les fournisseurs soumettent des factures conformes à l''EN 16931 (CIUS Peppol grec) pour validation par myDATA et attribution du MARK, puis transmission via des points d''accès Peppol accrédités au Centre national d''interopérabilité (KED).', '["Confirmez que votre point d''accès Peppol est accrédité pour le CIUS grec", "Vérifiez si votre organisme public spécifique se situe dans le seuil de marché de 2 500 €"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase1-2026', 'es', 'Mandato de facturación electrónica B2B nacional — comienza la Fase 1', 'La facturación electrónica B2B estructurada se vuelve obligatoria para empresas con ingresos anuales superiores a 1 millón de euros, en virtud de una excepción de la UE (Decisión de Ejecución (UE) 2025/502 del Consejo) que autoriza a Grecia a apartarse de los artículos 218 y 232 de la Directiva del IVA. Las facturas se validan a través del sistema de compensación myDATA antes de su intercambio. Un período transitorio de aplicación gradual se extendió hasta el 3 de mayo de 2026, durante el cual los fallos técnicos aislados no activaron el marco sancionador completo.', '["Confirme que su solución de facturación admite la compensación myDATA para B2B nacional", "Compruebe si sus ingresos anuales le sitúan en esta primera fase o en la segunda fase de octubre de 2026"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase1-2026', 'de', 'Inländische B2B-E-Rechnungspflicht — Phase 1 beginnt', 'Strukturierte B2B-E-Rechnung wird für Unternehmen mit einem Jahresumsatz über 1 Million Euro verpflichtend, im Rahmen einer EU-Ausnahmeregelung (Durchführungsbeschluss (EU) 2025/502 des Rates), die Griechenland ermächtigt, von den Artikeln 218 und 232 der Mehrwertsteuerrichtlinie abzuweichen. Rechnungen werden vor dem Austausch über das myDATA-Clearance-System validiert. Eine Übergangsphase mit abgestufter Durchsetzung lief bis zum 3. Mai 2026, in der isolierte technische Ausfälle nicht das volle Sanktionsregime auslösten.', '["Bestätigen Sie, dass Ihre Rechnungslösung die myDATA-Clearance für inländisches B2B unterstützt", "Prüfen Sie, ob Ihr Jahresumsatz Sie in diese erste Phase oder die zweite Phase im Oktober 2026 einordnet"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase1-2026', 'fr', 'Obligation nationale de facturation électronique B2B — début de la phase 1', 'La facturation électronique B2B structurée devient obligatoire pour les entreprises dont le chiffre d''affaires annuel dépasse 1 million d''euros, en vertu d''une dérogation de l''UE (décision d''exécution (UE) 2025/502 du Conseil) autorisant la Grèce à déroger aux articles 218 et 232 de la directive TVA. Les factures sont validées via le système de validation préalable myDATA avant échange. Une période transitoire à application graduée a couru jusqu''au 3 mai 2026, durant laquelle des défaillances techniques isolées n''ont pas déclenché le régime de sanctions complet.', '["Confirmez que votre solution de facturation prend en charge la validation préalable myDATA pour le B2B national", "Vérifiez si votre chiffre d''affaires annuel vous place dans cette première phase ou dans la seconde phase d''octobre 2026"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase2-2026', 'es', 'El mandato B2B nacional se amplía a todas las empresas restantes', 'El mandato de facturación electrónica B2B nacional se amplía a todas las empresas griegas restantes, con un período de adaptación hasta el 31 de diciembre de 2026. La obligación cubre las transacciones B2B nacionales y las ventas B2B a entidades no pertenecientes a la UE; la facturación electrónica B2B intracomunitaria sigue siendo opcional por ahora. Las vías de cumplimiento incluyen proveedores de facturación electrónica certificados, la aplicación gratuita ''Timologio'' de AADE, o la integración directa del ERP a través de la API REST de myDATA.', '["Confirme su vía de cumplimiento (proveedor certificado, Timologio o integración directa por API) con suficiente antelación al plazo", "Tenga en cuenta que la facturación B2B intracomunitaria aún no es obligatoria — solo lo es la B2B nacional y con terceros países"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase2-2026', 'de', 'Die inländische B2B-Pflicht wird auf alle verbleibenden Unternehmen ausgeweitet', 'Die inländische B2B-E-Rechnungspflicht wird auf alle verbleibenden griechischen Unternehmen ausgeweitet, mit einer Anpassungsfrist bis zum 31. Dezember 2026. Die Pflicht umfasst inländische B2B-Umsätze und B2B-Verkäufe an Nicht-EU-Einheiten; die innergemeinschaftliche B2B-E-Rechnung bleibt vorerst freiwillig. Zu den Erfüllungswegen zählen zertifizierte E-Rechnungsanbieter, die kostenlose ''Timologio''-App der AADE oder die direkte ERP-Integration über die myDATA-REST-API.', '["Bestätigen Sie Ihren Erfüllungsweg (zertifizierter Anbieter, Timologio oder direkte API-Integration) rechtzeitig vor der Frist", "Beachten Sie, dass die innergemeinschaftliche B2B-Rechnungsstellung noch nicht verpflichtend ist — nur inländisches und Nicht-EU-B2B"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase2-2026', 'fr', 'L''obligation B2B nationale s''étend à toutes les entreprises restantes', 'L''obligation nationale de facturation électronique B2B s''étend à toutes les entreprises grecques restantes, avec une période d''adaptation jusqu''au 31 décembre 2026. L''obligation couvre les transactions B2B nationales et les ventes B2B à des entités hors UE ; la facturation électronique B2B intracommunautaire reste optionnelle pour l''instant. Les voies de conformité incluent des fournisseurs de facturation électronique certifiés, l''application gratuite ''Timologio'' de l''AADE, ou l''intégration ERP directe via l''API REST myDATA.', '["Confirmez votre voie de conformité (fournisseur certifié, Timologio ou intégration API directe) bien avant l''échéance", "Notez que la facturation B2B intracommunautaire n''est pas encore obligatoire — seules le sont le B2B national et hors UE"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-vida-2030', 'es', 'Entra en vigor el reporte digital B2B transfronterizo de ViDA', 'Independientemente del alcance y calendario propios del mandato nacional, la directiva del IVA en la Era Digital (ViDA) de la UE exige capacidad de facturación electrónica estructurada y reporte digital para las transacciones B2B transfronterizas a partir del 1 de julio de 2030 — derecho de la UE confirmado (Directiva (UE) 2025/516 del Consejo).', '["Las empresas que comercien de forma transfronteriza dentro de la UE deberían prepararse para tener capacidad de facturación electrónica y reporte conforme a EN 16931 para esta fecha"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-vida-2030', 'de', 'Die grenzüberschreitende B2B-Digitalmeldung nach ViDA tritt in Kraft', 'Unabhängig vom Umfang und Zeitplan der inländischen Pflicht verlangt die EU-Richtlinie VAT in the Digital Age (ViDA) ab dem 1. Juli 2030 strukturierte E-Rechnungs- und digitale Meldefähigkeit für grenzüberschreitende B2B-Umsätze — bestätigtes EU-Recht (Richtlinie (EU) 2025/516 des Rates).', '["Unternehmen mit grenzüberschreitendem Handel innerhalb der EU sollten bis zu diesem Datum EN-16931-konforme E-Rechnungs- und Meldefähigkeit einplanen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-vida-2030', 'fr', 'La déclaration numérique B2B transfrontalière ViDA entre en vigueur', 'Quels que soient le périmètre et le calendrier propres de l''obligation nationale, la directive européenne TVA à l''ère numérique (ViDA) exige une capacité de facturation électronique structurée et de déclaration numérique pour les transactions B2B transfrontalières à partir du 1er juillet 2030 — droit de l''UE confirmé (directive (UE) 2025/516 du Conseil).', '["Les entreprises réalisant du commerce transfrontalier au sein de l''UE devraient se préparer à disposer d''une capacité de facturation électronique et de déclaration conforme à l''EN 16931 d''ici cette date"]');
